data.realtimejsadapter-socketio#@realtimejs/a:
The official Socket.IO transport layer. It bridges the gap between Socket.IO's bidirectional event architecture and RealtimeJS's standard adapter contract.
import { createSocketIOAdapter } from '@realtimejs/adapter-socketio';
const transport = createSocketIOAdapter('https://your-socket-server.com');

data.realtimejsadapter-websocket#@realtimejs/:
The official native WebSocket transport layer. It utilizes the browser's native WebSocket API, requiring absolutely no third-party dependencies. Perfect for Edge environments.
import { createWebSocketAdapter } from '@realtimejs/adapter-websocket';
const transport = createWebSocketAdapter('wss://your-websocket-server.com/ws');

data.realtimejsadapter-postgres#@realtimejs/a:
The official PostgreSQL adapter. It operates as a blazing-fast schemaless document store using a single JSONB column, allowing it to seamlessly handle highly dynamic realtime objects (like reactions or editing history) without requiring constant schema migrations.
import { createPostgresAdapter } from '@realtimejs/adapter-postgres';
const database = createPostgresAdapter('postgres://user:pass@localhost:5432/realtime');

data.realtimejsadapter-s3#@realtimejs/adapter:
The official AWS S3 storage adapter. Safely upload media using PutObjectCommand and automatically resolve public edge-cached URLs.
import { createS3Adapter } from '@realtimejs/adapter-s3';
const storage = createS3Adapter('my-realtime-bucket', 'us-east-1');

data.the-transportadapter-interface#The Trans:
To build a custom adapter, you simply need to implement the TransportAdapter interface.
import type { TransportAdapter } from '@realtimejs/core';
export function createMyCustomAdapter(): TransportAdapter {
  return {
    connect: async () => {
      // Your connection logic
    },
    disconnect: async () => {
      // Your disconnection logic
    },
    emit: async (event: string, payload: unknown) => {
      // Send data to your server
    },
    subscribe: (event: string, callback: (payload: unknown) => void) => {
      // Listen for data from your server
      return () => { /* return unsubscribe function */ };
    },
    isConnected: () => {
      // Return boolean status
      return true; 
    },
    onConnect: (callback: () => void) => {
      return () => {};
    },
    onDisconnect: (callback: () => void) => {
      return () => {};
    }
  };
}

data.validating-your-adapter#Validating Your:
The hardest part of building a custom transport is ensuring it behaves exactly like the official ones (handling edge cases, reconnects, etc.).RealtimeJS ships with a Contract Test Suite. You can import this into your Vitest or Jest setup and pass your custom adapter into it. If it passes the test suite, you are 100% guaranteed it will work perfectly with the React SDK.
import { runTransportAdapterContractTests } from '@realtimejs/core/src/adapters/ContractTestSuite';
import { createMyCustomAdapter } from './MyCustomAdapter';
describe('MyCustomAdapter', () => {
  // This will run 20+ assertions against your custom adapter!
  runTransportAdapterContractTests(() => createMyCustomAdapter());
});

data.accessing-message-status#Accessing Messa:
If you are building a custom UI, you can visually distinguish queued messages by reading the status property on the Message object.
import { useMessages } from '@realtimejs/react';
function CustomMessageList() {
  const { messages } = useMessages();
  return (
    <ul>
      {messages.map(msg => (
        <li key={msg.id} style={{ opacity: msg.status === 'sending' ? 0.5 : 1 }}>
          {msg.content} 
          {msg.status === 'failed' && <span className="error">Failed to send</span>}
        </li>
      ))}
    </ul>
  );
}

data.basic-initialization#Basic Initializatio:
To initialize RealtimeJS, you need to create an adapter and pass it into the createRealtime factory.
import { createRealtime } from '@realtimejs/core';
import { createSocketIOAdapter } from '@realtimejs/adapter-socketio';
// 1. Create a transport adapter pointing to your backend
const transport = createSocketIOAdapter('http://localhost:3000');
// 2. Initialize the core engine
const client = createRealtime({ transport });
// 3. Connect to the server
await client.connection.connect();

data.sending-a-message#Sending a Message:
Once connected, you can interact with the various modules seamlessly.
// Send a message
const message = await client.chat.sendMessage('room-1', 'Hello World!', 'user-123');
// Listen for incoming messages
client.chat.onMessage((msg) => {
  console.log('Received:', msg.content);
});
Check out the React SDK section for documentation on how to use our highly optimized React hooks and UI components!

data.setup#Setup:
Wrap your application in the RealtimeProvider.
import { RealtimeProvider } from '@realtimejs/react';
import { createRealtime } from '@realtimejs/core';
import { createSocketIOAdapter } from '@realtimejs/adapter-socketio';
const client = createRealtime({ 
  transport: createSocketIOAdapter('http://localhost:3000') 
});
export function App() {
  return (
    <RealtimeProvider client={client}>
      <YourApp />
    </RealtimeProvider>
  );
}

data.chatprovider--extensible-components#Chat:
RealtimeJS includes headless hooks, but it also provides beautiful, accessible, and completely extensible drop-in UI components.
import { Chat, ChatProvider, useChatContext } from '@realtimejs/react';
function QuickChat() {
  return (
    <ChatProvider roomId="room-1" userId="user-123">
      {/* 
        The <Chat /> component accepts a `components` prop allowing you 
        to inject your own CustomMessage, CustomInput, or CustomIndicator components!
      */}
      <Chat 
        roomId="room-1" 
        userId="user-123" 
        components={{ MessageInput: MyCustomInput }}
      />
    </ChatProvider>
  );
}
// Building a custom input is trivially simple using the Context hook!
function MyCustomInput() {
  const { sendMessage } = useChatContext();
  return (
    <button onClick={() => sendMessage('Hello World!')}>
      Quick Send
    </button>
  );
}

data.global-ui-settings#Global UI Settings:
You can expose a beautiful settings menu for your users to instantly toggle read receipts, presence, and other features.
import { UIConfigProvider, useUIConfig } from '@realtimejs/react';
function SettingsMenu() {
  const { features, updateConfig } = useUIConfig();
  return (
    <label>
      Enable Read Receipts
      <input 
        type="checkbox" 
        checked={features.ENABLE_READ_RECEIPTS} 
        onChange={(e) => updateConfig({ 
          features: { ...features, ENABLE_READ_RECEIPTS: e.target.checked } 
        })}
      />
    </label>
  );
}
